const results = {};
results.realSupported = !!(window.SpeechRecognition || window.webkitSpeechRecognition);
// Count /api/chat requests to prove nothing is auto-sent.
let chatCalls = 0; const realFetch = window.fetch;
window.fetch = (url, opts) => { if (String(url).includes("/api/chat")) chatCalls++; return realFetch(url, opts); };
// Drop the real listener by cloning the button, then init with the fake.
const old = document.getElementById("mic"); old.replaceWith(old.cloneNode(true));
let fake;
class FakeRecognition { constructor() { fake = this; } start() { this.onstart(); } stop() { this.onend(); } abort() { this.onerror({error: "aborted"}); this.onend(); } }
initVoice(FakeRecognition);
const mic = document.getElementById("mic"), box = document.getElementById("input"), status = document.getElementById("voice-status");
const r = (t, final) => { const res = [{transcript: t}]; res.isFinal = final; return res; };
box.value = "Hi"; box.dispatchEvent(new Event("input"));
mic.click();
results.listening = [mic.textContent, mic.getAttribute("aria-pressed"), status.textContent];
fake.onresult({results: [r("which hubs in the", false)]});
results.interim = box.value;
fake.onresult({results: [r("which hubs in the Midwest", true)]});
results.final = box.value;
mic.click();  // second press stops
results.stopped = [mic.textContent, mic.getAttribute("aria-pressed"), status.textContent];
results.count = document.getElementById("count").textContent;
// Error path
mic.click(); fake.onerror({error: "not-allowed"}); fake.onend();
results.error = [status.textContent, status.className, box.value];
// Send while listening: abort, late result must not refill the box
mic.click(); fake.onresult({results: [r("extra words", false)]});
document.getElementById("form").requestSubmit();
fake.onresult({results: [r("late result", true)]});
results.afterSend = {box: box.value, mic: mic.textContent};
results.hintVisible = !document.getElementById("voice-hint").hidden;
results.chatCallsBeforeSend = "see afterSend; total chat calls: " + chatCalls;
results

